    private static final BigDecimal TAXA_FIXA = new BigDecimal("18.00");
    private static final BigDecimal PESO_MAXIMO_KG = new BigDecimal("5");

    @Override
    public ModalidadeEntrega getModalidade() {
        return ModalidadeEntrega.MOTOBOY;
